window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0cba9ab02b9ec705"]={"versions": [{"id": "FIG-0cba9ab02b9ec705", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2) der AUTOSAR Classic Platform (<em>Software Component Template</em>, <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release 4.3.1).</li>\n<li><strong>Architektonischer Zweck:</strong> Formale Spezifikation von Aufzählungstypen (<em>Enumerations</em>) und diskreten Wertebereichs-Abbildungen (Text-to-Value bzw. Value-to-Text).</li>\n<li><strong>Einordnung im Gesamtsystem:</strong> Definiert das Zusammenspiel zwischen Datentyp-Eigenschaften (<code>SwDataDefProps</code>) und Umrechnungsvorschriften (<code>CompuMethod</code>). Es bildet die normative Basis für:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Die Generierung von C-Typdefinitionen (<code>typedef</code>, <code>enum</code> bzw. Makro-Konstanten) durch den RTE-Generator.</li>\n<li>Die Erzeugung von Kalibrier- und Messbeschreibungen (ASAM MCD-2 MC / A2L, z. B. <code>COMPU_VTAB</code> / <code>COMPU_VTAB_RANGE</code>).</li>\n<li>Die Diagnose- und DLT-Interpretation (Symbolischer Klartext vs. interner Integer-Rohwert).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwDataDefProps</code></strong> (<code>«atpVariation»</code>):</li>\n</ul>\n<p class=\"fig-p\">Zentraler Eigenschaftscontainer für Software-Daten (z. B. Variablen, Parameter, Datentypen). Enthält softwaretechnische Attribute:</p>\n<ul class=\"fig-list\">\n<li><code>additionalNativeTypeQualifier: NativeDeclarationString [0..1]</code></li>\n<li><code>displayFormat: DisplayFormatString [0..1]</code></li>\n<li><code>stepSize: Float [0..1]</code></li>\n<li><code>swAlignment: AlignmentType [0..1]</code></li>\n<li><code>swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code></li>\n<li><code>swImplPolicy: SwImplPolicyEnum [0..1]</code></li>\n<li><code>swIntendedResolution: Numerical [0..1]</code></li>\n<li><code>swInterpolationMethod: Identifier [0..1]</code></li>\n<li><code>swIsVirtual: Boolean [0..1]</code></li>\n<li><code>swValueBlockSize: Numerical [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><strong><code>CompuMethod</code></strong> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>):</li>\n</ul>\n<p class=\"fig-p\">Eigenständiges, wiederverwendbares Paket-Element und Blueprint zur Festlegung semantischer Werteumwandlungen.</p>\n<ul class=\"fig-list\">\n<li>Attribut: <code>displayFormat: DisplayFormatString [0..1]</code>.</li>\n<li><strong><code>Compu</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Hüllenklasse zur Kapselung der Berechnungsrichtung und eventueller Standardwerte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuContent</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für Berechnungsinhalte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScales</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung (<code>Generalization</code>) von <code>CompuContent</code>; fasst diskrete Skalenabschnitte zusammen.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Definiert ein konkretes Intervall bzw. ein Einzelliteral der Enumeration.</p>\n<ul class=\"fig-list\">\n<li>Attribute:</li>\n<li><code>mask: PositiveInteger [0..1]</code> (Bitmaske für bitweise dekodierte Enums / Bitfelder).</li>\n<li><code>shortLabel: Identifier [0..1]</code> (Kurzbezeichner/Name des Skalenwerts).</li>\n<li><code>symbol: CIdentifier [0..1]</code> (Gültiger Bezeichner für die C-Code-Generierung).</li>\n<li><code>lowerLimit: Limit [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><code>upperLimit: Limit [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><strong><code>CompuScaleContents</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für Skaleninhalte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScaleConstantContents</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung von <code>CompuScaleContents</code>; bindet eine Konstante an die Skala an.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConst</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Repräsentiert einen konstanten Ersatz- oder Standardwert.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConstContent</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für den konkreten Datentyp des konstanten Inhalts.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConstTextContent</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung von <code>CompuConstContent</code>; enthält das Attribut:</p>\n<ul class=\"fig-list\">\n<li><code>vt: VerbatimString</code> (textuelles Label / Klartext des Enumeration-Wertes).</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Kompositionen und Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwDataDefProps</code> $\\rightarrow$ <code>CompuMethod</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Unidirektionale Assoziation <code>+compuMethod</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuMethod</code> $\\rightarrow$ <code>Compu</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Kompositionen für Hin- und Rückrichtung:</p>\n<ul class=\"fig-list\">\n<li><code>+compuInternalToPhys [0..1]</code>: Wandlung vom internen Integer-Repräsentanten zum symbolischen/physikalischen Wert.</li>\n<li><code>+compuPhysToInternal [0..1]</code>: Inverse Wandlung.</li>\n<li><strong><code>Compu</code> $\\rightarrow$ <code>CompuContent</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Strikte Komposition <code>+compuContent [1]</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>Compu</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuDefaultValue [0..1]</code> (Definiert den Rückfallwert bei ungültigen / nicht gemappten Rohwerten).</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScales</code> $\\rightarrow$ <code>CompuScale</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuScale [0..*] {ordered}</code> unter <code>«atpVariation»</code>. Tag: <code>vh.latestBindingTime = blueprintDerivationTime</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code> $\\rightarrow$ <code>CompuScaleContents</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuScaleContents [0..1]</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Assoziation <code>+compuInverseValue [0..1]</code> zur expliziten Angabe des inversen Rechenwertes.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScaleConstantContents</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuConst [1]</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConst</code> $\\rightarrow$ <code>CompuConstContent</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuConstContentType [1]</code>.</p>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein deklaratives M2-Strukturmetamodell handelt, existiert kein CPU-Laufzeit-Zustandsautomat. Der Transformationsprozess zur Build- und Konfigurationszeit gliedert sich in folgende Phasen:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[ARXML M2 Model]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼ (1. Variantenbindung: evaluate «atpVariation» bis blueprintDerivationTime)</p>\n<p class=\"fig-p\">[Resolved Model]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">├────────────────────────────────────────┬──────────────────────────────────────┐</p>\n<p class=\"fig-p\">▼ (2. RTE Contract / Generation Phase)   ▼ (3. A2L Export Phase)                ▼ (4. Runtime Eval)</p>\n<p class=\"fig-p\">[RTE Header (*_Type.h)]                [ASAM MCD-2 MC File]                  [Signal Decoding]</p>\n<ul class=\"fig-list\">\n<li>Generiere Typdefinition               - COMPU_VTAB / COMPU_VTAB_RANGE       - Lese Rohwert (Internal)</li>\n<li>Generiere Literale:                   - Zuordnung vt <-> Limits/Mask        - Prüfe [lowerLimit..upperLimit]</li>\n</ul>\n<p class=\"fig-p\">Verwende <code>symbol</code> (Priorität)                                               - Treffer -> Symbol (vt)</p>\n<p class=\"fig-p\">oder <code>shortLabel</code>                                                           - Kein Treffer -> <code>compuDefaultValue</code></p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>Variantenauflösung:</strong> Attribute mit <code>«atpVariation»</code> (<code>lowerLimit</code>, <code>upperLimit</code>, <code>compuScale</code>) werden spätestens zur <code>blueprintDerivationTime</code> gebunden.</li>\n<li><strong>Generierung der C-Header (RTE/BSW):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für jede <code>CompuScale</code> wird das Literal generiert.</li>\n<li>Falls <code>symbol</code> vorhanden ist, dient dieser String als C-Macro- oder Enum-Bezeichner; andernfalls wird <code>shortLabel</code> herangezogen.</li>\n<li>Der numerische Wert wird aus <code>lowerLimit</code> / <code>upperLimit</code> (bei Enums identisch) abgeleitet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>MCD/A2L-Generierung:</strong> Das Tupel aus <code>vt</code> (<code>CompuConstTextContent</code>) und dem Wertebereich (<code>lowerLimit</code>, <code>upperLimit</code>, <code>mask</code>) wird in eine <code>COMPU_VTAB</code> bzw. <code>COMPU_TAB</code> übersetzt.</li>\n<li><strong>Auswertung bei Signalempfang (Deserialisierung):</strong> Liegt ein interner Wert außerhalb aller definierten <code>CompuScale</code>-Bereiche, bestimmt <code>compuDefaultValue</code> das deterministische Rückfallverhalten im Treiber-/Stack-Kontext.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Priorität bei der C-Code-Generierung (<code>symbol</code> vs. <code>shortLabel</code>):</strong></li>\n<li><code>CompuScale.symbol</code> besitzt den Datentyp <code>CIdentifier</code>. Es ist zwingend C-konform (keine Leerzeichen, keine Sonderzeichen außer Unterstrich, keine führenden Ziffern).</li>\n<li>Generatoren müssen bevorzugt <code>symbol</code> für C-Header-Dateien verwenden. Fehlt <code>symbol</code>, wird auf <code>shortLabel</code> zurückgegriffen (dieses muss dann den C-Namenskonventionen entsprechen).</li>\n<li><strong>Bitfeld- vs. Aufzählungs-Semantik:</strong></li>\n<li>Durch das Vorhandensein von <code>mask: PositiveInteger</code> können Bitmasken deklariert werden. Embedded-Treiber/Stacks dürfen bei gesetzter Maske nicht auf strikte Gleichheit (<code>val == limit</code>), sondern müssen auf maskierte Übereinstimmung (<code>(val &amp; mask) == limit</code>) prüfen.</li>\n<li><strong>Numerische Konsistenz & Datentypen:</strong></li>\n<li><code>lowerLimit</code> und <code>upperLimit</code> sind vom Typ <code>Limit</code>. Für klassische Enumerationen müssen beide Limits denselben ganzzahligen Wert aufweisen und das Intervall als geschlossen (<code>intervalType = CLOSED</code>) deklariert sein.</li>\n<li>Der Wertebereich der Limits muss strikt in den Wertebereich des durch <code>SwDataDefProps</code> referenzierten <code>BaseType</code> (z. B. <code>uint8</code>, <code>uint16</code>) passen; Wertebereichsüberläufe führen zu Generator-Fehlern.</li>\n<li><strong>Rückfall-Absicherung (<code>compuDefaultValue</code>):</strong></li>\n<li>Das Fehlen von <code>compuDefaultValue</code> führt bei nicht-abgedeckten Rohwerten zu undefiniertem Verhalten im Diagnose- und Kalibrier-Stack. Für sicherheitsrelevante Typen (ASIL) sollte stets ein <code>compuDefaultValue</code> (z. B. ein expliziter <code>INVALID</code>-Zustand) definiert werden.</li>\n</ul>"}, {"id": "FIG-ededa51c77dc91f5", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2) der AUTOSAR Classic Platform (<em>Software Component Template</em>, <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release 4.3.1).</li>\n<li><strong>Architektonischer Zweck:</strong> Formale Spezifikation von Aufzählungstypen (<em>Enumerations</em>) und diskreten Wertebereichs-Abbildungen (Text-to-Value bzw. Value-to-Text).</li>\n<li><strong>Einordnung im Gesamtsystem:</strong> Definiert das Zusammenspiel zwischen Datentyp-Eigenschaften (<code>SwDataDefProps</code>) und Umrechnungsvorschriften (<code>CompuMethod</code>). Es bildet die normative Basis für:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Die Generierung von C-Typdefinitionen (<code>typedef</code>, <code>enum</code> bzw. Makro-Konstanten) durch den RTE-Generator.</li>\n<li>Die Erzeugung von Kalibrier- und Messbeschreibungen (ASAM MCD-2 MC / A2L, z. B. <code>COMPU_VTAB</code> / <code>COMPU_VTAB_RANGE</code>).</li>\n<li>Die Diagnose- und DLT-Interpretation (Symbolischer Klartext vs. interner Integer-Rohwert).</li>\n</ol>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwDataDefProps</code></strong> (<code>«atpVariation»</code>):</li>\n</ul>\n<p class=\"fig-p\">Zentraler Eigenschaftscontainer für Software-Daten (z. B. Variablen, Parameter, Datentypen). Enthält softwaretechnische Attribute:</p>\n<ul class=\"fig-list\">\n<li><code>additionalNativeTypeQualifier: NativeDeclarationString [0..1]</code></li>\n<li><code>displayFormat: DisplayFormatString [0..1]</code></li>\n<li><code>displayPresentation: DisplayPresentationEnum [0..1]</code></li>\n<li><code>stepSize: Float [0..1]</code></li>\n<li><code>swAlignment: AlignmentType [0..1]</code></li>\n<li><code>swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code></li>\n<li><code>swImplPolicy: SwImplPolicyEnum [0..1]</code></li>\n<li><code>swIntendedResolution: Numerical [0..1]</code></li>\n<li><code>swInterpolationMethod: Identifier [0..1]</code></li>\n<li><code>swIsVirtual: Boolean [0..1]</code></li>\n<li><code>swValueBlockSize: Numerical [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><code>swValueBlockSizeMult: Numerical [0..*] {ordered}</code> (<code>«atpVariation»</code>)</li>\n<li><strong><code>CompuMethod</code></strong> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>):</li>\n</ul>\n<p class=\"fig-p\">Eigenständiges, wiederverwendbares Paket-Element und Blueprint zur Festlegung semantischer Werteumwandlungen.</p>\n<ul class=\"fig-list\">\n<li>Attribut: <code>displayFormat: DisplayFormatString [0..1]</code>.</li>\n<li><strong><code>Compu</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Hüllenklasse zur Kapselung der Berechnungsrichtung und eventueller Standardwerte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuContent</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für Berechnungsinhalte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScales</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung (<code>Generalization</code>) von <code>CompuContent</code>; fasst diskrete Skalenabschnitte zusammen.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Definiert ein konkretes Intervall bzw. ein Einzelliteral der Enumeration.</p>\n<ul class=\"fig-list\">\n<li>Attribute:</li>\n<li><code>mask: PositiveInteger [0..1]</code> (Bitmaske für bitweise dekodierte Enums / Bitfelder).</li>\n<li><code>shortLabel: Identifier [0..1]</code> (Kurzbezeichner/Name des Skalenwerts).</li>\n<li><code>symbol: CIdentifier [0..1]</code> (Gültiger Bezeichner für die C-Code-Generierung).</li>\n<li><code>lowerLimit: Limit [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><code>upperLimit: Limit [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><strong><code>CompuScaleContents</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für Skaleninhalte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScaleConstantContents</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung von <code>CompuScaleContents</code>; bindet eine Konstante an die Skala an.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConst</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Repräsentiert einen konstanten Ersatz- oder Standardwert.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConstContent</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für den konkreten Datentyp des konstanten Inhalts.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConstTextContent</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung von <code>CompuConstContent</code>; enthält das Attribut:</p>\n<ul class=\"fig-list\">\n<li><code>vt: VerbatimString</code> (textuelles Label / Klartext des Enumeration-Wertes).</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Kompositionen und Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwDataDefProps</code> $\\rightarrow$ <code>CompuMethod</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Unidirektionale Assoziation <code>+compuMethod</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuMethod</code> $\\rightarrow$ <code>Compu</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Kompositionen für Hin- und Rückrichtung:</p>\n<ul class=\"fig-list\">\n<li><code>+compuInternalToPhys</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+compuPhysToInternal</code> mit Multiplizität <code>0..1</code></li>\n<li><strong><code>Compu</code> $\\rightarrow$ <code>CompuContent</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuContent</code> mit Multiplizität <code>1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>Compu</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuDefaultValue</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScales</code> $\\rightarrow$ <code>CompuScale</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuScale</code> mit Multiplizität <code>0..* {ordered}</code> (<code>«atpVariation»</code>).</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code> $\\rightarrow$ <code>CompuScaleContents</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuScaleContents</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Assoziation <code>+compuInverseValue</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScaleConstantContents</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Assoziation <code>+compuConst</code> mit Multiplizität <code>1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConst</code> $\\rightarrow$ <code>CompuConstContent</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuConstContentType</code> mit Multiplizität <code>1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong>Generalisierungen:</strong></li>\n<li><code>CompuScales</code> erbt von <code>CompuContent</code>.</li>\n<li><code>CompuScaleConstantContents</code> erbt von <code>CompuScaleContents</code>.</li>\n<li><code>CompuConstTextContent</code> erbt von <code>CompuConstContent</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein deklaratives M2-Strukturmetamodell handelt, existiert kein CPU-Laufzeit-Zustandsautomat. Der Transformationsprozess zur Build- und Konfigurationszeit gliedert sich in folgende Phasen:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[ARXML M2 Model]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼ (1. Variantenbindung: evaluate «atpVariation» bis blueprintDerivationTime)</p>\n<p class=\"fig-p\">[Resolved Model]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">├────────────────────────────────────────┬──────────────────────────────────────┐</p>\n<p class=\"fig-p\">▼ (2. RTE Contract / Generation Phase)   ▼ (3. A2L Export Phase)                ▼ (4. Runtime Eval)</p>\n<p class=\"fig-p\">[RTE Header (*_Type.h)]                [ASAM MCD-2 MC File]                  [Signal Decoding]</p>\n<ul class=\"fig-list\">\n<li>Generiere Typdefinition               - COMPU_VTAB / COMPU_VTAB_RANGE       - Lese Rohwert (Internal)</li>\n<li>Generiere Literale:                   - Zuordnung vt <-> Limits/Mask        - Prüfe [lowerLimit..upperLimit]</li>\n</ul>\n<p class=\"fig-p\">Verwende <code>symbol</code> (Priorität)                                               - Treffer -> Symbol (vt)</p>\n<p class=\"fig-p\">oder <code>shortLabel</code>                                                           - Kein Treffer -> <code>compuDefaultValue</code></p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>Variantenauflösung:</strong> Attribute mit <code>«atpVariation»</code> (<code>lowerLimit</code>, <code>upperLimit</code>, <code>compuScale</code>) werden spätestens zur <code>blueprintDerivationTime</code> gebunden.</li>\n<li><strong>Generierung der C-Header (RTE/BSW):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für jede <code>CompuScale</code> wird das Literal generiert.</li>\n<li>Falls <code>symbol</code> vorhanden ist, dient dieser String als C-Macro- oder Enum-Bezeichner; andernfalls wird <code>shortLabel</code> herangezogen.</li>\n<li>Der numerische Wert wird aus <code>lowerLimit</code> / <code>upperLimit</code> (bei Enums identisch) abgeleitet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>MCD/A2L-Generierung:</strong> Das Tupel aus <code>vt</code> (<code>CompuConstTextContent</code>) und dem Wertebereich (<code>lowerLimit</code>, <code>upperLimit</code>, <code>mask</code>) wird in eine <code>COMPU_VTAB</code> bzw. <code>COMPU_TAB</code> übersetzt.</li>\n<li><strong>Auswertung bei Signalempfang (Deserialisierung):</strong> Liegt ein interner Wert außerhalb aller definierten <code>CompuScale</code>-Bereiche, bestimmt <code>compuDefaultValue</code> das deterministische Rückfallverhalten im Treiber-/Stack-Kontext.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Priorität bei der C-Code-Generierung (<code>symbol</code> vs. <code>shortLabel</code>):</strong></li>\n<li><code>CompuScale.symbol</code> besitzt den Datentyp <code>CIdentifier</code>. Es ist zwingend C-konform (keine Leerzeichen, keine Sonderzeichen außer Unterstrich, keine führenden Ziffern).</li>\n<li>Generatoren müssen bevorzugt <code>symbol</code> für C-Header-Dateien verwenden. Fehlt <code>symbol</code>, wird auf <code>shortLabel</code> zurückgegriffen (dieses muss dann den C-Namenskonventionen entsprechen).</li>\n<li><strong>Bitfeld- vs. Aufzählungs-Semantik:</strong></li>\n<li>Durch das Vorhandensein von <code>mask: PositiveInteger</code> können Bitmasken deklariert werden. Embedded-Treiber/Stacks dürfen bei gesetzter Maske nicht auf strikte Gleichheit (<code>val == limit</code>), sondern müssen auf maskierte Übereinstimmung (<code>(val &amp; mask) == limit</code>) prüfen.</li>\n<li><strong>Numerische Konsistenz & Datentypen:</strong></li>\n<li><code>lowerLimit</code> und <code>upperLimit</code> sind vom Typ <code>Limit</code>. Für klassische Enumerationen müssen beide Limits denselben ganzzahligen Wert aufweisen und das Intervall als geschlossen (<code>intervalType = CLOSED</code>) deklariert sein.</li>\n<li>Der Wertebereich der Limits muss strikt in den Wertebereich des durch <code>SwDataDefProps</code> referenzierten <code>BaseType</code> (z. B. <code>uint8</code>, <code>uint16</code>) passen; Wertebereichsüberläufe führen zu Generator-Fehlern.</li>\n<li><strong>Rückfall-Absicherung (<code>compuDefaultValue</code>):</strong></li>\n<li>Das Fehlen von <code>compuDefaultValue</code> führt bei nicht-abgedeckten Rohwerten zu undefiniertem Verhalten im Diagnose- und Kalibrier-Stack. Für sicherheitsrelevante Typen (ASIL) sollte stets ein <code>compuDefaultValue</code> (z. B. ein expliziter <code>INVALID</code>-Zustand) definiert werden.</li>\n</ul>"}, {"id": "FIG-954a192befaf9eb5", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2) der AUTOSAR Classic Platform (<em>Software Component Template</em>, <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release 4.3.1).</li>\n<li><strong>Architektonischer Zweck:</strong> Formale Spezifikation von Aufzählungstypen (<em>Enumerations</em>) und diskreten Wertebereichs-Abbildungen (Text-to-Value bzw. Value-to-Text).</li>\n<li><strong>Einordnung im Gesamtsystem:</strong> Definiert das Zusammenspiel zwischen Datentyp-Eigenschaften (<code>SwDataDefProps</code>) und Umrechnungsvorschriften (<code>CompuMethod</code>). Es bildet die normative Basis für:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Die Generierung von C-Typdefinitionen (<code>typedef</code>, <code>enum</code> bzw. Makro-Konstanten) durch den RTE-Generator.</li>\n<li>Die Erzeugung von Kalibrier- und Messbeschreibungen (ASAM MCD-2 MC / A2L, z. B. <code>COMPU_VTAB</code> / <code>COMPU_VTAB_RANGE</code>).</li>\n<li>Die Diagnose- und DLT-Interpretation (Symbolischer Klartext vs. interner Integer-Rohwert).</li>\n</ol>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwDataDefProps</code></strong> (<code>«atpVariation»</code>):</li>\n</ul>\n<p class=\"fig-p\">Zentraler Eigenschaftscontainer für Software-Daten (z. B. Variablen, Parameter, Datentypen). Enthält softwaretechnische Attribute:</p>\n<ul class=\"fig-list\">\n<li><code>additionalNativeTypeQualifier: NativeDeclarationString [0..1]</code></li>\n<li><code>displayFormat: DisplayFormatString [0..1]</code></li>\n<li><code>displayPresentation: DisplayPresentationEnum [0..1]</code></li>\n<li><code>stepSize: Float [0..1]</code></li>\n<li><code>swAlignment: AlignmentType [0..1]</code></li>\n<li><code>swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code></li>\n<li><code>swImplPolicy: SwImplPolicyEnum [0..1]</code></li>\n<li><code>swIntendedResolution: Numerical [0..1]</code></li>\n<li><code>swInterpolationMethod: Identifier [0..1]</code></li>\n<li><code>swIsVirtual: Boolean [0..1]</code></li>\n<li><code>swValueBlockSize: Numerical [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><code>swValueBlockSizeMult: Numerical [0..*] {ordered}</code> (<code>«atpVariation»</code>)</li>\n<li><strong><code>CompuMethod</code></strong> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>):</li>\n</ul>\n<p class=\"fig-p\">Eigenständiges, wiederverwendbares Paket-Element und Blueprint zur Festlegung semantischer Werteumwandlungen.</p>\n<ul class=\"fig-list\">\n<li>Attribut: <code>displayFormat: DisplayFormatString [0..1]</code>.</li>\n<li><strong><code>Compu</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Hüllenklasse zur Kapselung der Berechnungsrichtung und eventueller Standardwerte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuContent</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für Berechnungsinhalte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScales</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung (<code>Generalization</code>) von <code>CompuContent</code>; fasst diskrete Skalenabschnitte zusammen.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Definiert ein konkretes Intervall bzw. ein Einzelliteral der Enumeration.</p>\n<ul class=\"fig-list\">\n<li>Attribute:</li>\n<li><code>mask: PositiveInteger [0..1]</code> (Bitmaske für bitweise dekodierte Enums / Bitfelder).</li>\n<li><code>shortLabel: Identifier [0..1]</code> (Kurzbezeichner/Name des Skalenwerts).</li>\n<li><code>symbol: CIdentifier [0..1]</code> (Gültiger Bezeichner für die C-Code-Generierung).</li>\n<li><code>lowerLimit: Limit [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><code>upperLimit: Limit [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><strong><code>CompuScaleContents</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für Skaleninhalte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScaleConstantContents</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung von <code>CompuScaleContents</code>; bindet eine Konstante an die Skala an.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConst</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Repräsentiert einen konstanten Ersatz- oder Standardwert.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConstContent</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für den konkreten Datentyp des konstanten Inhalts.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConstTextContent</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung von <code>CompuConstContent</code>; enthält das Attribut:</p>\n<ul class=\"fig-list\">\n<li><code>vt: VerbatimString [0..1]</code> (textuelles Label / Klartext des Enumeration-Wertes).</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Kompositionen und Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwDataDefProps</code> $\\rightarrow$ <code>CompuMethod</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Unidirektionale Assoziation <code>+compuMethod</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuMethod</code> $\\rightarrow$ <code>Compu</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Kompositionen für Hin- und Rückrichtung:</p>\n<ul class=\"fig-list\">\n<li><code>+compuInternalToPhys</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+compuPhysToInternal</code> mit Multiplizität <code>0..1</code></li>\n<li><strong><code>Compu</code> $\\rightarrow$ <code>CompuContent</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuContent</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>Compu</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuDefaultValue</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScales</code> $\\rightarrow$ <code>CompuScale</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuScale</code> mit Multiplizität <code>0..* {ordered}</code> (<code>«atpVariation»</code>).</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code> $\\rightarrow$ <code>CompuScaleContents</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuScaleContents</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Assoziation <code>+compuInverseValue</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScaleConstantContents</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Assoziation <code>+compuConst</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConst</code> $\\rightarrow$ <code>CompuConstContent</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuConstContentType</code> mit Multiplizität <code>0..1</code> (Quell- und Zielkardinalität <code>0..1</code>).</p>\n<ul class=\"fig-list\">\n<li><strong>Generalisierungen:</strong></li>\n<li><code>CompuScales</code> erbt von <code>CompuContent</code>.</li>\n<li><code>CompuScaleConstantContents</code> erbt von <code>CompuScaleContents</code>.</li>\n<li><code>CompuConstTextContent</code> erbt von <code>CompuConstContent</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein deklaratives M2-Strukturmetamodell handelt, existiert kein CPU-Laufzeit-Zustandsautomat. Der Transformationsprozess zur Build- und Konfigurationszeit gliedert sich in folgende Phasen:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[ARXML M2 Model]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼ (1. Variantenbindung: evaluate «atpVariation» bis blueprintDerivationTime)</p>\n<p class=\"fig-p\">[Resolved Model]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">├────────────────────────────────────────┬──────────────────────────────────────┐</p>\n<p class=\"fig-p\">▼ (2. RTE Contract / Generation Phase)   ▼ (3. A2L Export Phase)                ▼ (4. Runtime Eval)</p>\n<p class=\"fig-p\">[RTE Header (*_Type.h)]                [ASAM MCD-2 MC File]                  [Signal Decoding]</p>\n<ul class=\"fig-list\">\n<li>Generiere Typdefinition               - COMPU_VTAB / COMPU_VTAB_RANGE       - Lese Rohwert (Internal)</li>\n<li>Generiere Literale:                   - Zuordnung vt <-> Limits/Mask        - Prüfe [lowerLimit..upperLimit]</li>\n</ul>\n<p class=\"fig-p\">Verwende <code>symbol</code> (Priorität)                                               - Treffer -> Symbol (vt)</p>\n<p class=\"fig-p\">oder <code>shortLabel</code>                                                           - Kein Treffer -> <code>compuDefaultValue</code></p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>Variantenauflösung:</strong> Attribute mit <code>«atpVariation»</code> (<code>lowerLimit</code>, <code>upperLimit</code>, <code>compuScale</code>) werden spätestens zur <code>blueprintDerivationTime</code> gebunden.</li>\n<li><strong>Generierung der C-Header (RTE/BSW):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für jede <code>CompuScale</code> wird das Literal generiert.</li>\n<li>Falls <code>symbol</code> vorhanden ist, dient dieser String als C-Macro- oder Enum-Bezeichner; andernfalls wird <code>shortLabel</code> herangezogen.</li>\n<li>Der numerische Wert wird aus <code>lowerLimit</code> / <code>upperLimit</code> (bei Enums identisch) abgeleitet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>MCD/A2L-Generierung:</strong> Das Tupel aus <code>vt</code> (<code>CompuConstTextContent</code>) und dem Wertebereich (<code>lowerLimit</code>, <code>upperLimit</code>, <code>mask</code>) wird in eine <code>COMPU_VTAB</code> bzw. <code>COMPU_TAB</code> übersetzt.</li>\n<li><strong>Auswertung bei Signalempfang (Deserialisierung):</strong> Liegt ein interner Wert außerhalb aller definierten <code>CompuScale</code>-Bereiche, bestimmt <code>compuDefaultValue</code> das deterministische Rückfallverhalten im Treiber-/Stack-Kontext.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Priorität bei der C-Code-Generierung (<code>symbol</code> vs. <code>shortLabel</code>):</strong></li>\n<li><code>CompuScale.symbol</code> besitzt den Datentyp <code>CIdentifier</code>. Es ist zwingend C-konform (keine Leerzeichen, keine Sonderzeichen außer Unterstrich, keine führenden Ziffern).</li>\n<li>Generatoren müssen bevorzugt <code>symbol</code> für C-Header-Dateien verwenden. Fehlt <code>symbol</code>, wird auf <code>shortLabel</code> zurückgegriffen (dieses muss dann den C-Namenskonventionen entsprechen).</li>\n<li><strong>Bitfeld- vs. Aufzählungs-Semantik:</strong></li>\n<li>Durch das Vorhandensein von <code>mask: PositiveInteger</code> können Bitmasken deklariert werden. Embedded-Treiber/Stacks dürfen bei gesetzter Maske nicht auf strikte Gleichheit (<code>val == limit</code>), sondern müssen auf maskierte Übereinstimmung (<code>(val &amp; mask) == limit</code>) prüfen.</li>\n<li><strong>Numerische Konsistenz & Datentypen:</strong></li>\n<li><code>lowerLimit</code> und <code>upperLimit</code> sind vom Typ <code>Limit</code>. Für klassische Enumerationen müssen beide Limits denselben ganzzahligen Wert aufweisen und das Intervall als geschlossen (<code>intervalType = CLOSED</code>) deklariert sein.</li>\n<li>Der Wertebereich der Limits muss strikt in den Wertebereich des durch <code>SwDataDefProps</code> referenzierten <code>BaseType</code> (z. B. <code>uint8</code>, <code>uint16</code>) passen; Wertebereichsüberläufe führen zu Generator-Fehlern.</li>\n<li><strong>Rückfall-Absicherung (<code>compuDefaultValue</code>):</strong></li>\n<li>Das Fehlen von <code>compuDefaultValue</code> führt bei nicht-abgedeckten Rohwerten zu undefiniertem Verhalten im Diagnose- und Kalibrier-Stack. Für sicherheitsrelevante Typen (ASIL) sollte stets ein <code>compuDefaultValue</code> (z. B. ein expliziter <code>INVALID</code>-Zustand) definiert werden.</li>\n</ul>"}, {"id": "FIG-38807911fe0de1d3", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2) der AUTOSAR Classic Platform (<em>Software Component Template</em>, <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release 4.3.1).</li>\n<li><strong>Architektonischer Zweck:</strong> Formale Spezifikation von Aufzählungstypen (<em>Enumerations</em>) und diskreten Wertebereichs-Abbildungen (Text-to-Value bzw. Value-to-Text).</li>\n<li><strong>Einordnung im Gesamtsystem:</strong> Definiert das Zusammenspiel zwischen Datentyp-Eigenschaften (<code>SwDataDefProps</code>) und Umrechnungsvorschriften (<code>CompuMethod</code>). Es bildet die normative Basis für:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Die Generierung von C-Typdefinitionen (<code>typedef</code>, <code>enum</code> bzw. Makro-Konstanten) durch den RTE-Generator.</li>\n<li>Die Erzeugung von Kalibrier- und Messbeschreibungen (ASAM MCD-2 MC / A2L, z. B. <code>COMPU_VTAB</code> / <code>COMPU_VTAB_RANGE</code>).</li>\n<li>Die Diagnose- und DLT-Interpretation (Symbolischer Klartext vs. interner Integer-Rohwert).</li>\n</ol>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwDataDefProps</code></strong> (<code>«atpVariation»</code>):</li>\n</ul>\n<p class=\"fig-p\">Zentraler Eigenschaftscontainer für Software-Daten (z. B. Variablen, Parameter, Datentypen).</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuMethod</code></strong> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>):</li>\n</ul>\n<p class=\"fig-p\">Eigenständiges, wiederverwendbares Paket-Element und Blueprint zur Festlegung semantischer Werteumwandlungen.</p>\n<ul class=\"fig-list\">\n<li>Attribut: <code>displayFormat: DisplayFormatString [0..1]</code>.</li>\n<li><strong><code>Compu</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Hüllenklasse zur Kapselung der Berechnungsrichtung und eventueller Standardwerte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuContent</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für Berechnungsinhalte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScales</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung (<code>Generalization</code>) von <code>CompuContent</code>; fasst diskrete Skalenabschnitte zusammen.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Definiert ein konkretes Intervall bzw. ein Einzelliteral der Enumeration.</p>\n<ul class=\"fig-list\">\n<li>Attribute:</li>\n<li><code>mask: PositiveUnlimitedInteger [0..1]</code> (Bitmaske für bitweise dekodierte Enums / Bitfelder).</li>\n<li><code>shortLabel: Identifier [0..1]</code> (Kurzbezeichner/Name des Skalenwerts).</li>\n<li><code>symbol: CIdentifier [0..1]</code> (Gültiger Bezeichner für die C-Code-Generierung).</li>\n<li><code>lowerLimit: Limit [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><code>upperLimit: Limit [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><strong><code>CompuScaleContents</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für Skaleninhalte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScaleConstantContents</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung von <code>CompuScaleContents</code>; bindet eine Konstante an die Skala an.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConst</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Repräsentiert einen konstanten Ersatz- oder Standardwert.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConstContent</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für den konkreten Datentyp des konstanten Inhalts.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConstTextContent</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung von <code>CompuConstContent</code>; enthält das Attribut:</p>\n<ul class=\"fig-list\">\n<li><code>vt: VerbatimString [0..1]</code> (textuelles Label / Klartext des Enumeration-Wertes).</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Kompositionen und Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwDataDefProps</code> $\\rightarrow$ <code>CompuMethod</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Unidirektionale Assoziation <code>+compuMethod</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuMethod</code> $\\rightarrow$ <code>Compu</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Kompositionen für Hin- und Rückrichtung:</p>\n<ul class=\"fig-list\">\n<li><code>+compuInternalToPhys</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+compuPhysToInternal</code> mit Multiplizität <code>0..1</code></li>\n<li><strong><code>Compu</code> $\\rightarrow$ <code>CompuContent</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuContent</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>Compu</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuDefaultValue</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScales</code> $\\rightarrow$ <code>CompuScale</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuScale</code> mit Multiplizität <code>0..* {ordered}</code> (<code>«atpVariation,atpSplitable»</code>).</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code> $\\rightarrow$ <code>CompuScaleContents</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuScaleContents</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Assoziation <code>+compuInverseValue</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScaleConstantContents</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Assoziation <code>+compuConst</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConst</code> $\\rightarrow$ <code>CompuConstContent</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuConstContentType</code> mit Multiplizität <code>0..1</code> (Quell- und Zielkardinalität <code>0..1</code>).</p>\n<ul class=\"fig-list\">\n<li><strong>Generalisierungen:</strong></li>\n<li><code>CompuScales</code> erbt von <code>CompuContent</code>.</li>\n<li><code>CompuScaleConstantContents</code> erbt von <code>CompuScaleContents</code>.</li>\n<li><code>CompuConstTextContent</code> erbt von <code>CompuConstContent</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein deklaratives M2-Strukturmetamodell handelt, existiert kein CPU-Laufzeit-Zustandsautomat. Der Transformationsprozess zur Build- und Konfigurationszeit gliedert sich in folgende Phasen:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[ARXML M2 Model]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼ (1. Variantenbindung: evaluate «atpVariation» bis blueprintDerivationTime)</p>\n<p class=\"fig-p\">[Resolved Model]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">├────────────────────────────────────────┬──────────────────────────────────────┐</p>\n<p class=\"fig-p\">▼ (2. RTE Contract / Generation Phase)   ▼ (3. A2L Export Phase)                ▼ (4. Runtime Eval)</p>\n<p class=\"fig-p\">[RTE Header (*_Type.h)]                [ASAM MCD-2 MC File]                  [Signal Decoding]</p>\n<ul class=\"fig-list\">\n<li>Generiere Typdefinition               - COMPU_VTAB / COMPU_VTAB_RANGE       - Lese Rohwert (Internal)</li>\n<li>Generiere Literale:                   - Zuordnung vt <-> Limits/Mask        - Prüfe [lowerLimit..upperLimit]</li>\n</ul>\n<p class=\"fig-p\">Verwende <code>symbol</code> (Priorität)                                               - Treffer -> Symbol (vt)</p>\n<p class=\"fig-p\">oder <code>shortLabel</code>                                                           - Kein Treffer -> <code>compuDefaultValue</code></p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>Variantenauflösung:</strong> Attribute mit <code>«atpVariation»</code> (<code>lowerLimit</code>, <code>upperLimit</code>, <code>compuScale</code>) werden spätestens zur <code>blueprintDerivationTime</code> gebunden.</li>\n<li><strong>Generierung der C-Header (RTE/BSW):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für jede <code>CompuScale</code> wird das Literal generiert.</li>\n<li>Falls <code>symbol</code> vorhanden ist, dient dieser String als C-Macro- oder Enum-Bezeichner; andernfalls wird <code>shortLabel</code> herangezogen.</li>\n<li>Der numerische Wert wird aus <code>lowerLimit</code> / <code>upperLimit</code> (bei Enums identisch) abgeleitet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>MCD/A2L-Generierung:</strong> Das Tupel aus <code>vt</code> (<code>CompuConstTextContent</code>) und dem Wertebereich (<code>lowerLimit</code>, <code>upperLimit</code>, <code>mask</code>) wird in eine <code>COMPU_VTAB</code> bzw. <code>COMPU_TAB</code> übersetzt.</li>\n<li><strong>Auswertung bei Signalempfang (Deserialisierung):</strong> Liegt ein interner Wert außerhalb aller definierten <code>CompuScale</code>-Bereiche, bestimmt <code>compuDefaultValue</code> das deterministische Rückfallverhalten im Treiber-/Stack-Kontext.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Priorität bei der C-Code-Generierung (<code>symbol</code> vs. <code>shortLabel</code>):</strong></li>\n<li><code>CompuScale.symbol</code> besitzt den Datentyp <code>CIdentifier</code>. Es ist zwingend C-konform (keine Leerzeichen, keine Sonderzeichen außer Unterstrich, keine führenden Ziffern).</li>\n<li>Generatoren müssen bevorzugt <code>symbol</code> für C-Header-Dateien verwenden. Fehlt <code>symbol</code>, wird auf <code>shortLabel</code> zurückgegriffen (dieses muss dann den C-Namenskonventionen entsprechen).</li>\n<li><strong>Bitfeld- vs. Aufzählungs-Semantik:</strong></li>\n<li>Durch das Vorhandensein von <code>mask: PositiveInteger</code> können Bitmasken deklariert werden. Embedded-Treiber/Stacks dürfen bei gesetzter Maske nicht auf strikte Gleichheit (<code>val == limit</code>), sondern müssen auf maskierte Übereinstimmung (<code>(val &amp; mask) == limit</code>) prüfen.</li>\n<li><strong>Numerische Konsistenz & Datentypen:</strong></li>\n<li><code>lowerLimit</code> und <code>upperLimit</code> sind vom Typ <code>Limit</code>. Für klassische Enumerationen müssen beide Limits denselben ganzzahligen Wert aufweisen und das Intervall als geschlossen (<code>intervalType = CLOSED</code>) deklariert sein.</li>\n<li>Der Wertebereich der Limits muss strikt in den Wertebereich des durch <code>SwDataDefProps</code> referenzierten <code>BaseType</code> (z. B. <code>uint8</code>, <code>uint16</code>) passen; Wertebereichsüberläufe führen zu Generator-Fehlern.</li>\n<li><strong>Rückfall-Absicherung (<code>compuDefaultValue</code>):</strong></li>\n<li>Das Fehlen von <code>compuDefaultValue</code> führt bei nicht-abgedeckten Rohwerten zu undefiniertem Verhalten im Diagnose- und Kalibrier-Stack. Für sicherheitsrelevante Typen (ASIL) sollte stets ein <code>compuDefaultValue</code> (z. B. ein expliziter <code>INVALID</code>-Zustand) definiert werden.</li>\n</ul>"}, {"id": "FIG-7d4d52bda7633ff7", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2) der AUTOSAR Classic Platform (<em>Software Component Template</em>, <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release 4.3.1).</li>\n<li><strong>Architektonischer Zweck:</strong> Formale Spezifikation von Aufzählungstypen (<em>Enumerations</em>) und diskreten Wertebereichs-Abbildungen (Text-to-Value bzw. Value-to-Text).</li>\n<li><strong>Einordnung im Gesamtsystem:</strong> Definiert das Zusammenspiel zwischen Datentyp-Eigenschaften (<code>SwDataDefProps</code>) und Umrechnungsvorschriften (<code>CompuMethod</code>). Es bildet die normative Basis für:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Die Generierung von C-Typdefinitionen (<code>typedef</code>, <code>enum</code> bzw. Makro-Konstanten) durch den RTE-Generator.</li>\n<li>Die Erzeugung von Kalibrier- und Messbeschreibungen (ASAM MCD-2 MC / A2L, z. B. <code>COMPU_VTAB</code> / <code>COMPU_VTAB_RANGE</code>).</li>\n<li>Die Diagnose- und DLT-Interpretation (Symbolischer Klartext vs. interner Integer-Rohwert).</li>\n</ol>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwDataDefProps</code></strong> (<code>«atpVariation»</code>):</li>\n</ul>\n<p class=\"fig-p\">Zentraler Eigenschaftscontainer für Software-Daten (z. B. Variablen, Parameter, Datentypen).</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuMethod</code></strong> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>):</li>\n</ul>\n<p class=\"fig-p\">Eigenständiges, wiederverwendbares Paket-Element und Blueprint zur Festlegung semantischer Werteumwandlungen.</p>\n<ul class=\"fig-list\">\n<li>Attribut: <code>displayFormat: DisplayFormatString [0..1]</code>.</li>\n<li><strong><code>Compu</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Hüllenklasse zur Kapselung der Berechnungsrichtung und eventueller Standardwerte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuContent</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für Berechnungsinhalte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScales</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung (<code>Generalization</code>) von <code>CompuContent</code>; fasst diskrete Skalenabschnitte zusammen.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Definiert ein konkretes Intervall bzw. ein Einzelliteral der Enumeration.</p>\n<ul class=\"fig-list\">\n<li>Attribute:</li>\n<li><code>a2lDisplayText: String [0..1]</code> (Anzeigetext für Kalibrier- und Messwerkzeuge / A2L).</li>\n<li><code>mask: PositiveUnlimitedInteger [0..1]</code> (Bitmaske für bitweise dekodierte Enums / Bitfelder).</li>\n<li><code>shortLabel: Identifier [0..1]</code> (Kurzbezeichner/Name des Skalenwerts).</li>\n<li><code>symbol: CIdentifier [0..1]</code> (Gültiger Bezeichner für die C-Code-Generierung).</li>\n<li><code>lowerLimit: Limit [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><code>upperLimit: Limit [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><strong><code>CompuScaleContents</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für Skaleninhalte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScaleConstantContents</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung von <code>CompuScaleContents</code>; bindet eine Konstante an die Skala an.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConst</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Repräsentiert einen konstanten Ersatz- oder Standardwert.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConstContent</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für den konkreten Datentyp des konstanten Inhalts.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConstTextContent</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung von <code>CompuConstContent</code>; enthält das Attribut:</p>\n<ul class=\"fig-list\">\n<li><code>vt: VerbatimString [0..1]</code> (textuelles Label / Klartext des Enumeration-Wertes).</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Kompositionen und Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwDataDefProps</code> $\\rightarrow$ <code>CompuMethod</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Unidirektionale Assoziation <code>+compuMethod</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuMethod</code> $\\rightarrow$ <code>Compu</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Kompositionen für Hin- und Rückrichtung:</p>\n<ul class=\"fig-list\">\n<li><code>+compuInternalToPhys</code> mit Multiplizität <code>0..1</code> (<code>«atpSplitable»</code>)</li>\n<li><code>+compuPhysToInternal</code> mit Multiplizität <code>0..1</code> (<code>«atpSplitable»</code>)</li>\n<li><strong><code>Compu</code> $\\rightarrow$ <code>CompuContent</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuContent</code> mit Multiplizität <code>0..1</code> (<code>«atpSplitable»</code>).</p>\n<ul class=\"fig-list\">\n<li><strong><code>Compu</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuDefaultValue</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScales</code> $\\rightarrow$ <code>CompuScale</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuScale</code> mit Multiplizität <code>0..* {ordered}</code> (<code>«atpVariation,atpSplitable»</code>).</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code> $\\rightarrow$ <code>CompuScaleContents</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuScaleContents</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Assoziation <code>+compuInverseValue</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScaleConstantContents</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Assoziation <code>+compuConst</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConst</code> $\\rightarrow$ <code>CompuConstContent</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuConstContentType</code> mit Multiplizität <code>0..1</code> (Quell- und Zielkardinalität <code>0..1</code>).</p>\n<ul class=\"fig-list\">\n<li><strong>Generalisierungen:</strong></li>\n<li><code>CompuScales</code> erbt von <code>CompuContent</code>.</li>\n<li><code>CompuScaleConstantContents</code> erbt von <code>CompuScaleContents</code>.</li>\n<li><code>CompuConstTextContent</code> erbt von <code>CompuConstContent</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein deklaratives M2-Strukturmetamodell handelt, existiert kein CPU-Laufzeit-Zustandsautomat. Der Transformationsprozess zur Build- und Konfigurationszeit gliedert sich in folgende Phasen:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[ARXML M2 Model]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼ (1. Variantenbindung: evaluate «atpVariation» bis blueprintDerivationTime)</p>\n<p class=\"fig-p\">[Resolved Model]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">├────────────────────────────────────────┬──────────────────────────────────────┐</p>\n<p class=\"fig-p\">▼ (2. RTE Contract / Generation Phase)   ▼ (3. A2L Export Phase)                ▼ (4. Runtime Eval)</p>\n<p class=\"fig-p\">[RTE Header (*_Type.h)]                [ASAM MCD-2 MC File]                  [Signal Decoding]</p>\n<ul class=\"fig-list\">\n<li>Generiere Typdefinition               - COMPU_VTAB / COMPU_VTAB_RANGE       - Lese Rohwert (Internal)</li>\n<li>Generiere Literale:                   - Zuordnung vt <-> Limits/Mask        - Prüfe [lowerLimit..upperLimit]</li>\n</ul>\n<p class=\"fig-p\">Verwende <code>symbol</code> (Priorität)                                               - Treffer -> Symbol (vt)</p>\n<p class=\"fig-p\">oder <code>shortLabel</code>                                                           - Kein Treffer -> <code>compuDefaultValue</code></p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>Variantenauflösung:</strong> Attribute mit <code>«atpVariation»</code> (<code>lowerLimit</code>, <code>upperLimit</code>, <code>compuScale</code>) werden spätestens zur <code>blueprintDerivationTime</code> gebunden.</li>\n<li><strong>Generierung der C-Header (RTE/BSW):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für jede <code>CompuScale</code> wird das Literal generiert.</li>\n<li>Falls <code>symbol</code> vorhanden ist, dient dieser String als C-Macro- oder Enum-Bezeichner; andernfalls wird <code>shortLabel</code> herangezogen.</li>\n<li>Der numerische Wert wird aus <code>lowerLimit</code> / <code>upperLimit</code> (bei Enums identisch) abgeleitet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>MCD/A2L-Generierung:</strong> Das Tupel aus <code>vt</code> (<code>CompuConstTextContent</code>) und dem Wertebereich (<code>lowerLimit</code>, <code>upperLimit</code>, <code>mask</code>) wird in eine <code>COMPU_VTAB</code> bzw. <code>COMPU_TAB</code> übersetzt.</li>\n<li><strong>Auswertung bei Signalempfang (Deserialisierung):</strong> Liegt ein interner Wert außerhalb aller definierten <code>CompuScale</code>-Bereiche, bestimmt <code>compuDefaultValue</code> das deterministische Rückfallverhalten im Treiber-/Stack-Kontext.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Priorität bei der C-Code-Generierung (<code>symbol</code> vs. <code>shortLabel</code>):</strong></li>\n<li><code>CompuScale.symbol</code> besitzt den Datentyp <code>CIdentifier</code>. Es ist zwingend C-konform (keine Leerzeichen, keine Sonderzeichen außer Unterstrich, keine führenden Ziffern).</li>\n<li>Generatoren müssen bevorzugt <code>symbol</code> für C-Header-Dateien verwenden. Fehlt <code>symbol</code>, wird auf <code>shortLabel</code> zurückgegriffen (dieses muss dann den C-Namenskonventionen entsprechen).</li>\n<li><strong>Bitfeld- vs. Aufzählungs-Semantik:</strong></li>\n<li>Durch das Vorhandensein von <code>mask: PositiveInteger</code> können Bitmasken deklariert werden. Embedded-Treiber/Stacks dürfen bei gesetzter Maske nicht auf strikte Gleichheit (<code>val == limit</code>), sondern müssen auf maskierte Übereinstimmung (<code>(val &amp; mask) == limit</code>) prüfen.</li>\n<li><strong>Numerische Konsistenz & Datentypen:</strong></li>\n<li><code>lowerLimit</code> und <code>upperLimit</code> sind vom Typ <code>Limit</code>. Für klassische Enumerationen müssen beide Limits denselben ganzzahligen Wert aufweisen und das Intervall als geschlossen (<code>intervalType = CLOSED</code>) deklariert sein.</li>\n<li>Der Wertebereich der Limits muss strikt in den Wertebereich des durch <code>SwDataDefProps</code> referenzierten <code>BaseType</code> (z. B. <code>uint8</code>, <code>uint16</code>) passen; Wertebereichsüberläufe führen zu Generator-Fehlern.</li>\n<li><strong>Rückfall-Absicherung (<code>compuDefaultValue</code>):</strong></li>\n<li>Das Fehlen von <code>compuDefaultValue</code> führt bei nicht-abgedeckten Rohwerten zu undefiniertem Verhalten im Diagnose- und Kalibrier-Stack. Für sicherheitsrelevante Typen (ASIL) sollte stets ein <code>compuDefaultValue</code> (z. B. ein expliziter <code>INVALID</code>-Zustand) definiert werden.</li>\n</ul>"}, {"id": "FIG-241d6401cd256ede", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2) der AUTOSAR Classic Platform (<em>Software Component Template</em>, <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release 4.3.1).</li>\n<li><strong>Architektonischer Zweck:</strong> Formale Spezifikation von Aufzählungstypen (<em>Enumerations</em>) und diskreten Wertebereichs-Abbildungen (Text-to-Value bzw. Value-to-Text).</li>\n<li><strong>Einordnung im Gesamtsystem:</strong> Definiert das Zusammenspiel zwischen Datentyp-Eigenschaften (<code>SwDataDefProps</code>) und Umrechnungsvorschriften (<code>CompuMethod</code>). Es bildet die normative Basis für:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Die Generierung von C-Typdefinitionen (<code>typedef</code>, <code>enum</code> bzw. Makro-Konstanten) durch den RTE-Generator.</li>\n<li>Die Erzeugung von Kalibrier- und Messbeschreibungen (ASAM MCD-2 MC / A2L, z. B. <code>COMPU_VTAB</code> / <code>COMPU_VTAB_RANGE</code>).</li>\n<li>Die Diagnose- und DLT-Interpretation (Symbolischer Klartext vs. interner Integer-Rohwert).</li>\n</ol>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwDataDefProps</code></strong> (<code>«atpVariation»</code>):</li>\n</ul>\n<p class=\"fig-p\">Zentraler Eigenschaftscontainer für Software-Daten (z. B. Variablen, Parameter, Datentypen).</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuMethod</code></strong> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>):</li>\n</ul>\n<p class=\"fig-p\">Eigenständiges, wiederverwendbares Paket-Element und Blueprint zur Festlegung semantischer Werteumwandlungen.</p>\n<ul class=\"fig-list\">\n<li>Attribut: <code>displayFormat: DisplayFormatString [0..1]</code>.</li>\n<li><strong><code>Compu</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Hüllenklasse zur Kapselung der Berechnungsrichtung und eventueller Standardwerte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuContent</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für Berechnungsinhalte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScales</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung (<code>Generalization</code>) von <code>CompuContent</code>; fasst diskrete Skalenabschnitte zusammen.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Definiert ein konkretes Intervall bzw. ein Einzelliteral der Enumeration.</p>\n<ul class=\"fig-list\">\n<li>Attribute:</li>\n<li><code>a2lDisplayText: String [0..1]</code> (Anzeigetext für Kalibrier- und Messwerkzeuge / A2L).</li>\n<li><code>mask: PositiveUnlimitedInteger [0..1]</code> (Bitmaske für bitweise dekodierte Enums / Bitfelder).</li>\n<li><code>shortLabel: Identifier [0..1]</code> (Kurzbezeichner/Name des Skalenwerts).</li>\n<li><code>symbol: CIdentifier [0..1]</code> (Gültiger Bezeichner für die C-Code-Generierung).</li>\n<li><code>lowerLimit: Limit [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><code>upperLimit: Limit [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><strong><code>CompuScaleContents</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für Skaleninhalte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScaleConstantContents</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung von <code>CompuScaleContents</code>; bindet eine Konstante an die Skala an.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConst</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Repräsentiert einen konstanten Ersatz- oder Standardwert.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConstContent</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für den konkreten Datentyp des konstanten Inhalts.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConstTextContent</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung von <code>CompuConstContent</code>; enthält das Attribut:</p>\n<ul class=\"fig-list\">\n<li><code>vt: VerbatimString [0..1]</code> (textuelles Label / Klartext des Enumeration-Wertes).</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Kompositionen und Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwDataDefProps</code> $\\rightarrow$ <code>CompuMethod</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Unidirektionale Assoziation <code>+compuMethod</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuMethod</code> $\\rightarrow$ <code>Compu</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Kompositionen für Hin- und Rückrichtung:</p>\n<ul class=\"fig-list\">\n<li><code>+compuInternalToPhys</code> mit Multiplizität <code>0..1</code> (<code>«atpSplitable»</code>)</li>\n<li><code>+compuPhysToInternal</code> mit Multiplizität <code>0..1</code> (<code>«atpSplitable»</code>)</li>\n<li><strong><code>Compu</code> $\\rightarrow$ <code>CompuContent</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuContent</code> mit Multiplizität <code>0..1</code> (<code>«atpSplitable»</code>).</p>\n<ul class=\"fig-list\">\n<li><strong><code>Compu</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuDefaultValue</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScales</code> $\\rightarrow$ <code>CompuScale</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuScale</code> mit Multiplizität <code>0..* {ordered}</code> (<code>«atpVariation,atpSplitable»</code>).</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code> $\\rightarrow$ <code>CompuScaleContents</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuScaleContents</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Assoziation <code>+compuInverseValue</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScaleConstantContents</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Assoziation <code>+compuConst</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConst</code> $\\rightarrow$ <code>CompuConstContent</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuConstContentType</code> mit Multiplizität <code>0..1</code> (Quell- und Zielkardinalität <code>0..1</code>).</p>\n<ul class=\"fig-list\">\n<li><strong>Generalisierungen:</strong></li>\n<li><code>CompuScales</code> erbt von <code>CompuContent</code>.</li>\n<li><code>CompuScaleConstantContents</code> erbt von <code>CompuScaleContents</code>.</li>\n<li><code>CompuConstTextContent</code> erbt von <code>CompuConstContent</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein deklaratives M2-Strukturmetamodell handelt, existiert kein CPU-Laufzeit-Zustandsautomat. Der Transformationsprozess zur Build- und Konfigurationszeit gliedert sich in folgende Phasen:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[ARXML M2 Model]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼ (1. Variantenbindung: evaluate «atpVariation» bis blueprintDerivationTime)</p>\n<p class=\"fig-p\">[Resolved Model]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">├────────────────────────────────────────┬──────────────────────────────────────┐</p>\n<p class=\"fig-p\">▼ (2. RTE Contract / Generation Phase)   ▼ (3. A2L Export Phase)                ▼ (4. Runtime Eval)</p>\n<p class=\"fig-p\">[RTE Header (*_Type.h)]                [ASAM MCD-2 MC File]                  [Signal Decoding]</p>\n<ul class=\"fig-list\">\n<li>Generiere Typdefinition               - COMPU_VTAB / COMPU_VTAB_RANGE       - Lese Rohwert (Internal)</li>\n<li>Generiere Literale:                   - Zuordnung vt <-> Limits/Mask        - Prüfe [lowerLimit..upperLimit]</li>\n</ul>\n<p class=\"fig-p\">Verwende <code>symbol</code> (Priorität)                                               - Treffer -> Symbol (vt)</p>\n<p class=\"fig-p\">oder <code>shortLabel</code>                                                           - Kein Treffer -> <code>compuDefaultValue</code></p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>Variantenauflösung:</strong> Attribute mit <code>«atpVariation»</code> (<code>lowerLimit</code>, <code>upperLimit</code>, <code>compuScale</code>) werden spätestens zur <code>blueprintDerivationTime</code> gebunden.</li>\n<li><strong>Generierung der C-Header (RTE/BSW):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für jede <code>CompuScale</code> wird das Literal generiert.</li>\n<li>Falls <code>symbol</code> vorhanden ist, dient dieser String als C-Macro- oder Enum-Bezeichner; andernfalls wird <code>shortLabel</code> herangezogen.</li>\n<li>Der numerische Wert wird aus <code>lowerLimit</code> / <code>upperLimit</code> (bei Enums identisch) abgeleitet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>MCD/A2L-Generierung:</strong> Das Tupel aus <code>vt</code> (<code>CompuConstTextContent</code>) und dem Wertebereich (<code>lowerLimit</code>, <code>upperLimit</code>, <code>mask</code>) wird in eine <code>COMPU_VTAB</code> bzw. <code>COMPU_TAB</code> übersetzt.</li>\n<li><strong>Auswertung bei Signalempfang (Deserialisierung):</strong> Liegt ein interner Wert außerhalb aller definierten <code>CompuScale</code>-Bereiche, bestimmt <code>compuDefaultValue</code> das deterministische Rückfallverhalten im Treiber-/Stack-Kontext.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Priorität bei der C-Code-Generierung (<code>symbol</code> vs. <code>shortLabel</code>):</strong></li>\n<li><code>CompuScale.symbol</code> besitzt den Datentyp <code>CIdentifier</code>. Es ist zwingend C-konform (keine Leerzeichen, keine Sonderzeichen außer Unterstrich, keine führenden Ziffern).</li>\n<li>Generatoren müssen bevorzugt <code>symbol</code> für C-Header-Dateien verwenden. Fehlt <code>symbol</code>, wird auf <code>shortLabel</code> zurückgegriffen (dieses muss dann den C-Namenskonventionen entsprechen).</li>\n<li><strong>Bitfeld- vs. Aufzählungs-Semantik:</strong></li>\n<li>Durch das Vorhandensein von <code>mask: PositiveInteger</code> können Bitmasken deklariert werden. Embedded-Treiber/Stacks dürfen bei gesetzter Maske nicht auf strikte Gleichheit (<code>val == limit</code>), sondern müssen auf maskierte Übereinstimmung (<code>(val &amp; mask) == limit</code>) prüfen.</li>\n<li><strong>Numerische Konsistenz & Datentypen:</strong></li>\n<li><code>lowerLimit</code> und <code>upperLimit</code> sind vom Typ <code>Limit</code>. Für klassische Enumerationen müssen beide Limits denselben ganzzahligen Wert aufweisen und das Intervall als geschlossen (<code>intervalType = CLOSED</code>) deklariert sein.</li>\n<li>Der Wertebereich der Limits muss strikt in den Wertebereich des durch <code>SwDataDefProps</code> referenzierten <code>BaseType</code> (z. B. <code>uint8</code>, <code>uint16</code>) passen; Wertebereichsüberläufe führen zu Generator-Fehlern.</li>\n<li><strong>Rückfall-Absicherung (<code>compuDefaultValue</code>):</strong></li>\n<li>Das Fehlen von <code>compuDefaultValue</code> führt bei nicht-abgedeckten Rohwerten zu undefiniertem Verhalten im Diagnose- und Kalibrier-Stack. Für sicherheitsrelevante Typen (ASIL) sollte stets ein <code>compuDefaultValue</code> (z. B. ein expliziter <code>INVALID</code>-Zustand) definiert werden.</li>\n</ul>"}, {"id": "FIG-d3396f650f246518", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2) der AUTOSAR Classic Platform (<em>Software Component Template</em>, <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>, Release 4.3.1).</li>\n<li><strong>Architektonischer Zweck:</strong> Formale Spezifikation von Aufzählungstypen (<em>Enumerations</em>) und diskreten Wertebereichs-Abbildungen (Text-to-Value bzw. Value-to-Text).</li>\n<li><strong>Einordnung im Gesamtsystem:</strong> Definiert das Zusammenspiel zwischen Datentyp-Eigenschaften (<code>SwDataDefProps</code>) und Umrechnungsvorschriften (<code>CompuMethod</code>). Es bildet die normative Basis für:</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Die Generierung von C-Typdefinitionen (<code>typedef</code>, <code>enum</code> bzw. Makro-Konstanten) durch den RTE-Generator.</li>\n<li>Die Erzeugung von Kalibrier- und Messbeschreibungen (ASAM MCD-2 MC / A2L, z. B. <code>COMPU_VTAB</code> / <code>COMPU_VTAB_RANGE</code>).</li>\n<li>Die Diagnose- und DLT-Interpretation (Symbolischer Klartext vs. interner Integer-Rohwert).</li>\n</ol>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwDataDefProps</code></strong> (<code>«atpVariation»</code>):</li>\n</ul>\n<p class=\"fig-p\">Zentraler Eigenschaftscontainer für Software-Daten (z. B. Variablen, Parameter, Datentypen).</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuMethod</code></strong> (<code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>):</li>\n</ul>\n<p class=\"fig-p\">Eigenständiges, wiederverwendbares Paket-Element und Blueprint zur Festlegung semantischer Werteumwandlungen.</p>\n<ul class=\"fig-list\">\n<li>Attribut: <code>displayFormat: DisplayFormatString [0..1]</code>.</li>\n<li><strong><code>Compu</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Hüllenklasse zur Kapselung der Berechnungsrichtung und eventueller Standardwerte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuContent</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für Berechnungsinhalte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScales</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung (<code>Generalization</code>) von <code>CompuContent</code>; fasst diskrete Skalenabschnitte zusammen.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Definiert ein konkretes Intervall bzw. ein Einzelliteral der Enumeration.</p>\n<ul class=\"fig-list\">\n<li>Attribute:</li>\n<li><code>a2lDisplayText: String [0..1]</code> (Anzeigetext für Kalibrier- und Messwerkzeuge / A2L).</li>\n<li><code>mask: PositiveUnlimitedInteger [0..1]</code> (Bitmaske für bitweise dekodierte Enums / Bitfelder).</li>\n<li><code>shortLabel: Identifier [0..1]</code> (Kurzbezeichner/Name des Skalenwerts).</li>\n<li><code>symbol: CIdentifier [0..1]</code> (Gültiger Bezeichner für die C-Code-Generierung).</li>\n<li><code>lowerLimit: Limit [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><code>upperLimit: Limit [0..1]</code> (<code>«atpVariation»</code>)</li>\n<li><strong><code>CompuScaleContents</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für Skaleninhalte.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScaleConstantContents</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung von <code>CompuScaleContents</code>; bindet eine Konstante an die Skala an.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConst</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Repräsentiert einen konstanten Ersatz- oder Standardwert.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConstContent</code></strong> <em>(abstrakt)</em>:</li>\n</ul>\n<p class=\"fig-p\">Basisklasse für den konkreten Datentyp des konstanten Inhalts.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConstTextContent</code></strong>:</li>\n</ul>\n<p class=\"fig-p\">Spezialisierung von <code>CompuConstContent</code>; enthält das Attribut:</p>\n<ul class=\"fig-list\">\n<li><code>vt: VerbatimString [0..1]</code> (textuelles Label / Klartext des Enumeration-Wertes).</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen, Kompositionen und Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwDataDefProps</code> $\\rightarrow$ <code>CompuMethod</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Unidirektionale Assoziation <code>+compuMethod</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuMethod</code> $\\rightarrow$ <code>Compu</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Kompositionen für Hin- und Rückrichtung:</p>\n<ul class=\"fig-list\">\n<li><code>+compuInternalToPhys</code> mit Multiplizität <code>0..1</code> (<code>«atpSplitable»</code>)</li>\n<li><code>+compuPhysToInternal</code> mit Multiplizität <code>0..1</code> (<code>«atpSplitable»</code>)</li>\n<li><strong><code>Compu</code> $\\rightarrow$ <code>CompuContent</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuContent</code> mit Multiplizität <code>0..1</code> (<code>«atpSplitable»</code>).</p>\n<ul class=\"fig-list\">\n<li><strong><code>Compu</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuDefaultValue</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScales</code> $\\rightarrow$ <code>CompuScale</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuScale</code> mit Multiplizität <code>0..* {ordered}</code> (<code>«atpVariation,atpSplitable»</code>).</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code> $\\rightarrow$ <code>CompuScaleContents</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuScaleContents</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScale</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Assoziation <code>+compuInverseValue</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuScaleConstantContents</code> $\\rightarrow$ <code>CompuConst</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Assoziation <code>+compuConst</code> mit Multiplizität <code>0..1</code>.</p>\n<ul class=\"fig-list\">\n<li><strong><code>CompuConst</code> $\\rightarrow$ <code>CompuConstContent</code>:</strong></li>\n</ul>\n<p class=\"fig-p\">Komposition <code>+compuConstContentType</code> mit Multiplizität <code>0..1</code> (Quell- und Zielkardinalität <code>0..1</code>).</p>\n<ul class=\"fig-list\">\n<li><strong>Generalisierungen:</strong></li>\n<li><code>CompuScales</code> erbt von <code>CompuContent</code>.</li>\n<li><code>CompuScaleConstantContents</code> erbt von <code>CompuScaleContents</code>.</li>\n<li><code>CompuConstTextContent</code> erbt von <code>CompuConstContent</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein deklaratives M2-Strukturmetamodell handelt, existiert kein CPU-Laufzeit-Zustandsautomat. Der Transformationsprozess zur Build- und Konfigurationszeit gliedert sich in folgende Phasen:</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[ARXML M2 Model]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼ (1. Variantenbindung: evaluate «atpVariation» bis blueprintDerivationTime)</p>\n<p class=\"fig-p\">[Resolved Model]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">├────────────────────────────────────────┬──────────────────────────────────────┐</p>\n<p class=\"fig-p\">▼ (2. RTE Contract / Generation Phase)   ▼ (3. A2L Export Phase)                ▼ (4. Runtime Eval)</p>\n<p class=\"fig-p\">[RTE Header (*_Type.h)]                [ASAM MCD-2 MC File]                  [Signal Decoding]</p>\n<ul class=\"fig-list\">\n<li>Generiere Typdefinition               - COMPU_VTAB / COMPU_VTAB_RANGE       - Lese Rohwert (Internal)</li>\n<li>Generiere Literale:                   - Zuordnung vt <-> Limits/Mask        - Prüfe [lowerLimit..upperLimit]</li>\n</ul>\n<p class=\"fig-p\">Verwende <code>symbol</code> (Priorität)                                               - Treffer -> Symbol (vt)</p>\n<p class=\"fig-p\">oder <code>shortLabel</code>                                                           - Kein Treffer -> <code>compuDefaultValue</code></p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>Variantenauflösung:</strong> Attribute mit <code>«atpVariation»</code> (<code>lowerLimit</code>, <code>upperLimit</code>, <code>compuScale</code>) werden spätestens zur <code>blueprintDerivationTime</code> gebunden.</li>\n<li><strong>Generierung der C-Header (RTE/BSW):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Für jede <code>CompuScale</code> wird das Literal generiert.</li>\n<li>Falls <code>symbol</code> vorhanden ist, dient dieser String als C-Macro- oder Enum-Bezeichner; andernfalls wird <code>shortLabel</code> herangezogen.</li>\n<li>Der numerische Wert wird aus <code>lowerLimit</code> / <code>upperLimit</code> (bei Enums identisch) abgeleitet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>MCD/A2L-Generierung:</strong> Das Tupel aus <code>vt</code> (<code>CompuConstTextContent</code>) und dem Wertebereich (<code>lowerLimit</code>, <code>upperLimit</code>, <code>mask</code>) wird in eine <code>COMPU_VTAB</code> bzw. <code>COMPU_TAB</code> übersetzt.</li>\n<li><strong>Auswertung bei Signalempfang (Deserialisierung):</strong> Liegt ein interner Wert außerhalb aller definierten <code>CompuScale</code>-Bereiche, bestimmt <code>compuDefaultValue</code> das deterministische Rückfallverhalten im Treiber-/Stack-Kontext.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Priorität bei der C-Code-Generierung (<code>symbol</code> vs. <code>shortLabel</code>):</strong></li>\n<li><code>CompuScale.symbol</code> besitzt den Datentyp <code>CIdentifier</code>. Es ist zwingend C-konform (keine Leerzeichen, keine Sonderzeichen außer Unterstrich, keine führenden Ziffern).</li>\n<li>Generatoren müssen bevorzugt <code>symbol</code> für C-Header-Dateien verwenden. Fehlt <code>symbol</code>, wird auf <code>shortLabel</code> zurückgegriffen (dieses muss dann den C-Namenskonventionen entsprechen).</li>\n<li><strong>Bitfeld- vs. Aufzählungs-Semantik:</strong></li>\n<li>Durch das Vorhandensein von <code>mask: PositiveInteger</code> können Bitmasken deklariert werden. Embedded-Treiber/Stacks dürfen bei gesetzter Maske nicht auf strikte Gleichheit (<code>val == limit</code>), sondern müssen auf maskierte Übereinstimmung (<code>(val &amp; mask) == limit</code>) prüfen.</li>\n<li><strong>Numerische Konsistenz & Datentypen:</strong></li>\n<li><code>lowerLimit</code> und <code>upperLimit</code> sind vom Typ <code>Limit</code>. Für klassische Enumerationen müssen beide Limits denselben ganzzahligen Wert aufweisen und das Intervall als geschlossen (<code>intervalType = CLOSED</code>) deklariert sein.</li>\n<li>Der Wertebereich der Limits muss strikt in den Wertebereich des durch <code>SwDataDefProps</code> referenzierten <code>BaseType</code> (z. B. <code>uint8</code>, <code>uint16</code>) passen; Wertebereichsüberläufe führen zu Generator-Fehlern.</li>\n<li><strong>Rückfall-Absicherung (<code>compuDefaultValue</code>):</strong></li>\n<li>Das Fehlen von <code>compuDefaultValue</code> führt bei nicht-abgedeckten Rohwerten zu undefiniertem Verhalten im Diagnose- und Kalibrier-Stack. Für sicherheitsrelevante Typen (ASIL) sollte stets ein <code>compuDefaultValue</code> (z. B. ein expliziter <code>INVALID</code>-Zustand) definiert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-0cba9ab02b9ec705", "to": "FIG-ededa51c77dc91f5", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>In Metaklasse <code>SwDataDefProps</code> wurden die Attribute <code>displayPresentation: DisplayPresentationEnum [0..1]</code> sowie <code>swValueBlockSizeMult: Numerical [0..*] {ordered}</code> (unter <code>«atpVariation»</code>) ergänzt.</li>\n</ul>"}, {"from": "FIG-ededa51c77dc91f5", "to": "FIG-954a192befaf9eb5", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kardinalität der Komposition <code>+compuContent</code> von <code>Compu</code> zu <code>CompuContent</code> von <code>1</code> auf <code>0..1</code> geändert.</li>\n<li>Kardinalität der Assoziation <code>+compuConst</code> von <code>CompuScaleConstantContents</code> zu <code>CompuConst</code> von <code>1</code> auf <code>0..1</code> geändert.</li>\n<li>Kardinalität der Komposition <code>+compuConstContentType</code> von <code>CompuConst</code> zu <code>CompuConstContent</code> von <code>1</code> (bzw. unqualifiziert) auf <code>0..1</code> (sowohl Quell- als auch Zielmultiplizität als <code>0..1</code> ausgewiesen) geändert.</li>\n<li>Attribut <code>vt: VerbatimString</code> in <code>CompuConstTextContent</code> wurde zu <code>vt: VerbatimString [0..1]</code> optionalisiert.</li>\n</ul>"}, {"from": "FIG-954a192befaf9eb5", "to": "FIG-38807911fe0de1d3", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Attribute der Metaklasse <code>SwDataDefProps</code> wurden ausgeblendet (nur noch Klassenrumpf mit Stereotyp <code>«atpVariation»</code> dargestellt).</li>\n<li>Typ des Attributs <code>mask</code> in Metaklasse <code>CompuScale</code> von <code>PositiveInteger [0..1]</code> auf <code>PositiveUnlimitedInteger [0..1]</code> geändert.</li>\n<li>Stereotyp der Kompositionsrolle <code>+compuScale</code> von <code>CompuScales</code> zu <code>CompuScale</code> um <code>«atpSplitable»</code> erweitert (<code>«atpVariation,atpSplitable»</code>).</li>\n</ul>"}, {"from": "FIG-38807911fe0de1d3", "to": "FIG-7d4d52bda7633ff7", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Attribut <code>a2lDisplayText: String [0..1]</code> in Metaklasse <code>CompuScale</code> ergänzt.</li>\n<li>Stereotyp <code>«atpSplitable»</code> an den Kompositionen <code>+compuPhysToInternal</code>, <code>+compuInternalToPhys</code> und <code>+compuContent</code> von <code>CompuMethod</code> bzw. <code>Compu</code> ergänzt.</li>\n</ul>"}, {"from": "FIG-7d4d52bda7633ff7", "to": "FIG-241d6401cd256ede", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Im Kommentar-Tag an <code>+compuScale</code> wurde die Reihenfolge der Tag-Einträge getauscht (<code>msr.id</code> steht nun vor <code>vh.latestBindingTime</code>).</li>\n</ul>"}, {"from": "FIG-241d6401cd256ede", "to": "FIG-d3396f650f246518", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
